def holding(title, rule, authority, explanation):
    assert len(explanation.split()) <= 350, (title, len(explanation.split()))
    return f'### {title}\n\n**Holding and operative rule:** {rule}\n\n**Authority:** {authority}\n\n**Controlling explanation:** {explanation}'

def vote(component, disposition, supporters, opponents):
    assert set(supporters).isdisjoint(opponents)
    assert set(supporters + opponents) == set(ROSTER)
    return {'component': component, 'disposition': disposition, 'supporting': supporters, 'opposing': opponents}

